<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/../config/delivery_control.php';
require_once __DIR__ . '/_delivery_control_ui.php';
$companyId=(int)COMPANY_ID;delivery_control_require_enabled($pdo,$companyId);$msg='';$err='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{dc_csrf_check((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
   if($action==='toggle'){$pdo->prepare('UPDATE delivery_control_vehicles SET active=IF(active=1,0,1),updated_at=NOW() WHERE company_id=? AND id=?')->execute([$companyId,$id]);$msg='Situação do veículo atualizada.';}
   else{$description=trim((string)($_POST['description']??''));if($description==='')throw new RuntimeException('Informe a descrição do veículo.');$plate=strtoupper(trim((string)($_POST['plate']??'')));$driver=trim((string)($_POST['driver_name']??''));$notes=trim((string)($_POST['notes']??''));if($id>0){$pdo->prepare('UPDATE delivery_control_vehicles SET description=?,plate=?,driver_name=?,notes=?,updated_at=NOW() WHERE company_id=? AND id=?')->execute([$description,$plate?:null,$driver?:null,$notes?:null,$companyId,$id]);$msg='Veículo atualizado.';}else{$pdo->prepare('INSERT INTO delivery_control_vehicles(company_id,description,plate,driver_name,notes) VALUES(?,?,?,?,?)')->execute([$companyId,$description,$plate?:null,$driver?:null,$notes?:null]);$msg='Veículo cadastrado.';}}
 }catch(Throwable $e){$err=$e->getMessage();}
}
$edit=null;$editId=(int)($_GET['edit']??0);if($editId>0){$st=$pdo->prepare('SELECT * FROM delivery_control_vehicles WHERE company_id=? AND id=?');$st->execute([$companyId,$editId]);$edit=$st->fetch(PDO::FETCH_ASSOC)?:null;}
$st=$pdo->prepare('SELECT * FROM delivery_control_vehicles WHERE company_id=? ORDER BY active DESC,description');$st->execute([$companyId]);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
$gridColumns=['descricao'=>'Descrição','placa'=>'Placa','motorista'=>'Motorista','observacoes'=>'Observações','situacao'=>'Situação','acoes'=>'Ações'];
$gridPrefs=dc_grid_preferences_load($pdo,$companyId,'veiculos',array_keys($gridColumns));
dc_page_start('Veículos de Entrega','delivery_vehicles');
?>
<div class="dc-head"><h1>Veículos de Entrega</h1><div class="dc-spacer"></div><a class="dc-btn" href="delivery_manifest.php">Romaneios</a></div><?php if($msg):?><div class="dc-alert"><?=dc_e($msg)?></div><?php endif;?><?php if($err):?><div class="dc-alert error"><?=dc_e($err)?></div><?php endif;?>
<form method="post" class="dc-card"><input type="hidden" name="csrf" value="<?=dc_e(dc_csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><input type="hidden" name="action" value="save"><div class="dc-card-head"><?=!empty($edit)?'Editar veículo':'Novo veículo'?></div><div class="dc-card-body"><div class="dc-grid"><div class="dc-field"><label>Descrição *</label><input name="description" required value="<?=dc_e($edit['description']??'')?>" placeholder="Ex.: Caminhão Mercedes 3/4"></div><div class="dc-field"><label>Placa</label><input name="plate" value="<?=dc_e($edit['plate']??'')?>"></div><div class="dc-field"><label>Motorista padrão</label><input name="driver_name" value="<?=dc_e($edit['driver_name']??'')?>"></div><div class="dc-field"><label>Observações</label><input name="notes" value="<?=dc_e($edit['notes']??'')?>"></div></div><div class="dc-actions" style="margin-top:12px"><button class="dc-btn primary">Salvar</button><?php if($edit):?><a class="dc-btn" href="delivery_vehicles.php">Cancelar edição</a><?php endif;?></div></div></form>
<div class="dc-card"><div class="dc-card-head with-grid-tools"><span>Veículos cadastrados <span class="dc-muted">• <?=count($rows)?> registro(s)</span></span><?php dc_grid_toolbar('veiculos',$gridColumns,$gridPrefs);?></div><div class="dc-card-body"><div class="dc-advanced-wrap"><table class="dc-data-grid" id="dcGrid-veiculos"><thead><tr>
<th data-col="descricao"><div class="dc-grid-th-inner">Descrição</div></th><th data-col="placa"><div class="dc-grid-th-inner">Placa</div></th><th data-col="motorista"><div class="dc-grid-th-inner">Motorista</div></th><th data-col="observacoes"><div class="dc-grid-th-inner">Observações</div></th><th data-col="situacao"><div class="dc-grid-th-inner">Situação</div></th><th data-col="acoes" class="dc-actions-col"><div class="dc-grid-th-inner">Ações</div></th>
</tr></thead><tbody>
<?php if(!$rows):?><tr><?php foreach(array_keys($gridColumns) as $c):?><td data-col="<?=dc_e($c)?>" class="<?=$c==='descricao'?'dc-empty-grid':''?>"><?=$c==='descricao'?'Nenhum veículo cadastrado.':''?></td><?php endforeach;?></tr><?php endif;?>
<?php foreach($rows as $r):?><tr><td data-col="descricao"><strong><?=dc_e($r['description'])?></strong></td><td data-col="placa"><?=dc_e($r['plate'])?></td><td data-col="motorista"><?=dc_e($r['driver_name'])?></td><td data-col="observacoes"><?=dc_e($r['notes']?:'—')?></td><td data-col="situacao"><span class="dc-badge <?=$r['active']?'ok':'bad'?>"><?=$r['active']?'Ativo':'Inativo'?></span></td><td data-col="acoes" class="dc-actions-col"><div class="dc-actions"><a class="dc-btn sm" href="delivery_vehicles.php?edit=<?=(int)$r['id']?>">Editar</a><form method="post"><input type="hidden" name="csrf" value="<?=dc_e(dc_csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="toggle"><button class="dc-btn sm"><?=$r['active']?'Inativar':'Ativar'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php dc_grid_script('veiculos',$gridColumns,$gridPrefs,['descricao'=>280,'placa'=>115,'motorista'=>220,'observacoes'=>300,'situacao'=>110,'acoes'=>190]); ?>
<?php dc_page_end(); ?>
